package main

import "fmt"

func doubleValue(n int) {
	n *= 2 // only changes local copy
}

func doublePointer(n *int) {
	*n *= 2 // modifies the original
}

func swap(a, b *int) {
	*a, *b = *b, *a
}

func main() {
	// Basic pointer operations
	x := 42
	p := &x

	fmt.Printf("Value of x: %d\n", x)
	fmt.Printf("Address of x: %p\n", p)
	fmt.Printf("Value via pointer: %d\n", *p)

	// Modify via pointer
	*p = 100
	fmt.Printf("x after *p=100: %d\n", x)

	// new(T)
	pi := new(int)
	fmt.Printf("new(int) zero value: %d\n", *pi)
	*pi = 99
	fmt.Printf("new(int) after assign: %d\n", *pi)

	// nil pointer check
	var nilPtr *int
	fmt.Println("nil pointer:", nilPtr == nil)

	// Without pointer — no change
	val := 5
	doubleValue(val)
	fmt.Println("After doubleValue:", val)

	// With pointer — changes original
	doublePointer(&val)
	fmt.Println("After doublePointer:", val)

	// Swap using pointers
	a, b := 10, 20
	fmt.Printf("Before swap: a=%d, b=%d\n", a, b)
	swap(&a, &b)
	fmt.Printf("After swap: a=%d, b=%d\n", a, b)
}
